// Original code-drawn world: ground positions remain independent of camera and animation.
export const TILE_X=27,TILE_Y=13.5;
export function project(x,y){return{x:(x-y)*TILE_X,y:(x+y)*TILE_Y}}
export function unproject(x,y){return{x:(x/TILE_X+y/TILE_Y)/2,y:(y/TILE_Y-x/TILE_X)/2}}
const INK='#626348';
function poly(c,pts,fill,stroke=null,width=1){c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.stroke()}}
function line(c,pts,color,width=2){c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.stroke()}
function ellipse(c,x,y,rx,ry,fill,stroke=null){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke()}}
function plane(c,x,y,w,h,fill,stroke){const p=[project(x,y),project(x+w,y),project(x+w,y+h),project(x,y+h)];poly(c,p.map(q=>[q.x,q.y]),fill,stroke);return p}
function rnd(n){const v=Math.sin(n*127.1+43.7)*43758.5453;return v-Math.floor(v)}
function local(c,x,y,draw){const p=project(x,y);c.save();c.translate(p.x,p.y);draw();c.restore()}
function shadow(c,x,y,w=40,h=13){ellipse(c,x,y,w,h,'#636b4520')}
function tree(c,x,y,s=1,kind=0){local(c,x,y,()=>{c.scale(s,s);shadow(c,25,6,57,15);poly(c,[[-5,0],[6,1],[8,-53],[-5,-54]],'#8b7958',INK);line(c,[[0,-25],[-18,-54]],'#7c7053',5);line(c,[[1,-33],[20,-64]],'#7c7053',5);line(c,[[1,-40],[3,-79]],'#7c7053',5);for(let i=0;i<19;i++){const a=i*2.4,r=10+Math.sqrt(i)*8;const xx=Math.cos(a)*r,yy=-74+Math.sin(a)*r*.65;ellipse(c,xx,yy,19+rnd(i+x)*10,16+rnd(i+y)*7,['#96a779','#acb486','#7e956e','#b5ba8d'][Math.floor(rnd(i+kind)*4)])}for(let i=0;i<25;i++){const xx=(rnd(i+x)*2-1)*41,yy=-77+(rnd(i+y)*2-1)*23;line(c,[[xx,yy],[xx+3,yy-2]],'#6c82554a',1.2)}line(c,[[-2,-3],[-1,-31]],'#a3916a',1.2)})}
function shrub(c,x,y,s=1){local(c,x,y,()=>{c.scale(s,s);shadow(c,8,0,29,9);for(let i=0;i<8;i++)ellipse(c,(i%4-1.5)*12,-7-Math.floor(i/4)*10-rnd(i+x)*7,12,12,['#879a72','#a0ad7e','#b2b68c'][i%3]);for(let i=0;i<5;i++){ellipse(c,-20+i*9,-10-rnd(i+y)*18,2.5,2.5,i%2?'#ead28b':'#faf4ce')}})}
function bench(c,x,y,flip=false){local(c,x,y,()=>{if(flip)c.scale(-1,1);shadow(c,3,5,43,11);line(c,[[-32,0],[-32,13]],'#53665b',4);line(c,[[31,0],[31,12]],'#53665b',4);poly(c,[[-40,-5],[24,-12],[44,-2],[-22,7]],'#bf9870',INK);for(let i=0;i<3;i++){const yy=-30+i*7;poly(c,[[-37,yy],[28,yy-7],[28,yy-2],[-37,yy+5]],['#d2ad7f','#c59c71','#d3b083'][i],INK,.65)}line(c,[[-35,-29],[-35,-4]],'#53665b',3);line(c,[[29,-36],[29,-10]],'#53665b',3);line(c,[[-40,-5],[-40,-15],[-29,-16]],'#53665b',2);line(c,[[35,-8],[35,-22],[26,-21]],'#53665b',2)})}
function slide(c,x,y){local(c,x,y,()=>{shadow(c,28,7,86,23);const teal='#71949a',deep='#52777d';for(const[xx,yy]of[[-32,0],[18,14],[-2,-18],[48,-5]])line(c,[[xx,yy],[xx,yy-91]],teal,6);poly(c,[[-36,-79],[14,-65],[50,-83],[0,-98]],'#b5ba8e',INK,1);poly(c,[[-36,-79],[14,-65],[14,-59],[-36,-73]],'#8e9b77',INK);poly(c,[[-46,-111],[4,-143],[61,-112],[12,-96]],'#d9b865',INK,1.2);poly(c,[[-46,-111],[12,-96],[12,-91],[-46,-106]],'#bf9e55',INK);line(c,[[4,-143],[12,-96]],'#f0d68d',1);line(c,[[4,-143],[35,-105]],'#f0d68d',1);for(let i=0;i<4;i++)line(c,[[-31+i*12,-80+i*3],[-31+i*12,-103+i*3]],deep,2);poly(c,[[13,-66],[38,-79],[85,-2],[71,11],[47,7]],'#d47c61',INK,1.3);poly(c,[[20,-66],[34,-73],[76,0],[65,5],[52,2]],'#eca183',null);line(c,[[14,-67],[49,5],[70,10],[83,-2]],'#f1b499',3);line(c,[[39,-81],[87,-4]],'#b9654c',3);line(c,[[-2,-96],[-48,-28]],deep,3);line(c,[[-28,-101],[-75,-34]],deep,3);for(let i=0;i<6;i++){const yy=-38-i*10,xx=-65+i*7;line(c,[[xx,yy],[xx+23,yy+7]],'#d1b774',3)}})}
function swing(c,x,y){local(c,x,y,()=>{shadow(c,8,0,91,19);for(const xx of[-60,60]){line(c,[[xx-15,4],[xx,-103],[xx+29,3]],'#7596a0',5);line(c,[[xx-11,1],[xx+22,1]],'#627e80',2)}line(c,[[-60,-104],[61,-104]],'#527985',6);for(const xx of[-27,30]){line(c,[[xx-10,-102],[xx-10,-28]],'#65634a',1.5);line(c,[[xx+10,-102],[xx+10,-28]],'#65634a',1.5);poly(c,[[xx-16,-28],[xx+8,-31],[xx+17,-25],[xx-9,-21]],'#dcb45a',INK);for(let i=0;i<12;i++)line(c,[[xx-11,-98+i*5],[xx-9,-96+i*5]],'#9d9b75',.8)}})}
function climbing(c,x,y){local(c,x,y,()=>{shadow(c,13,3,67,23);const a=[[-48,0],[-7,19],[49,-7],[8,-27]],h=83;for(let i=0;i<4;i++)line(c,[a[i],[a[i][0],a[i][1]-h]],i%2?'#77949a':'#c68061',4);for(let i=0;i<4;i++){const j=(i+1)%4;line(c,[[a[i][0],a[i][1]-h],[a[j][0],a[j][1]-h]],'#c68061',4)}for(let i=1;i<5;i++){const t=i/5;line(c,[[-48+41*t,-83+19*t],[-48+41*t,19*t]],'#c6a75c',2);line(c,[[-48,-83+i*16],[-7,-64+i*16]],'#c6a75c',2)}poly(c,[[-7,-64],[49,-90],[49,-8],[-7,18]],'#c5c3a4',INK,1);for(let i=0;i<9;i++)ellipse(c,1+rnd(i+9)*38,-67+rnd(i+3)*65,3.5,2.5,['#b66c52','#6f959c','#d5b664'][i%3],INK)})}
function sandpit(c,x,y){local(c,x,y,()=>{shadow(c,5,4,74,21);const a=[[-67,-12],[-8,-40],[70,-11],[8,23]];poly(c,a,'#ceb797',INK);poly(c,a.map(([x,y])=>[x*.85,y*.85-3]),'#ead2a7',null);line(c,[[-67,-12],[8,23],[70,-11]],'#ecdbc0',8);for(let i=0;i<65;i++)ellipse(c,(rnd(i+2)*2-1)*46,-7+(rnd(i+17)*2-1)*13,.7,.4,'#b79a6c60');poly(c,[[-17,-11],[-15,-29],[0,-29],[3,-11]],'#d2ac6a',INK);ellipse(c,-7.5,-29,8,3,'#ead09b',INK);poly(c,[[18,-4],[23,-21],[29,-19],[23,-3]],'#c77c5e',INK);line(c,[[25,-21],[30,-39]],'#b87056',2);ellipse(c,31,-40,3,3,'#ead6ad',INK)})}
function sign(c,x,y){local(c,x,y,()=>{line(c,[[0,2],[0,-59]],'#8d8a67',5);poly(c,[[-43,-67],[36,-67],[43,-52],[36,-36],[-43,-36]],'#f3efd9',INK,1.2);c.fillStyle='#647453';c.font='bold 12px sans-serif';c.textAlign='center';c.fillText('一起玩 ↗',-1,-48)})}
function seesaw(c,x,y){local(c,x,y,()=>{shadow(c,0,5,52,13);poly(c,[[-12,5],[2,-22],[18,8]],'#6a9194',INK);poly(c,[[-57,-23],[51,-5],[60,-11],[-48,-29]],'#cb8a69',INK);line(c,[[-38,-25],[-38,-39],[-28,-37]],'#556b60',2);line(c,[[38,-12],[38,-25],[46,-24]],'#556b60',2)})}
export function buildWorld(){const out=document.createElement('canvas');out.width=2700;out.height=1600;const c=out.getContext('2d');c.scale(1.5,1.5);c.translate(900,130);
// Whole park island, walking path, then continuous activity square.
plane(c,-5,-4,34,29,'#c3cbaa');plane(c,-3.6,-3,31.3,26.5,'#d8d7c4');plane(c,-1.5,-1.5,27,23,'#e8d8b6','#b6ad8b');
plane(c,-.5,-.5,25,21,'#c99479');plane(c,-.28,-.28,24.56,20.56,'#ebd9b9');
for(let y=0;y<20;y++)for(let x=0;x<24;x++)plane(c,x,y,1,1,['#e8d9ba','#eaddc3','#eadcc0','#e6d6b7'][Math.floor(rnd(x+y*24)*4)],'#b7aa8c25');
// Fine inset border and restrained ground graphics.
c.save();c.globalAlpha=.27;plane(c,.2,.2,23.6,19.6,null,'#f8f4da');c.restore();
local(c,4,15,()=>{c.save();c.transform(1,.5,-1,.5,0,0);c.strokeStyle='#f6efda';c.lineWidth=2;c.beginPath();c.arc(0,0,36,0,Math.PI*2);c.stroke();c.beginPath();c.arc(0,0,43,Math.PI*.1,Math.PI*1.6);c.stroke();c.restore()});
// Plantings are outside the computational rectangle.
for(const[x,y,s]of[[-4,0,1],[-3,4,.85],[-3,10,1],[-3,17,.9],[2,-3,.8],[7,-3,1],[15,-3,.9],[25,-2,1],[27,5,.9],[27,12,1],[26,19,.9],[19,23,.8],[10,23,.9],[0,23,1]])shrub(c,x,y,s);
const objects=[[-3,0,()=>tree(c,-3,0,1.05,2)],[5,-3,()=>tree(c,5,-3,.9)],[15,-3,()=>swing(c,15,-3)],[24,-2,()=>tree(c,24,-2,.9,2)],[-3,7,()=>climbing(c,-3,7)],[-3,14,()=>bench(c,-3,14)],[-3,20,()=>tree(c,-3,20,1.1)],[3,23,()=>sandpit(c,3,23)],[12,23,()=>bench(c,12,23)],[20,23,()=>tree(c,20,23,1)],[27,18,()=>sign(c,27,18)],[27,10,()=>slide(c,27,10)],[27,2,()=>tree(c,27,2,1.1)],[-1,-3,()=>bench(c,-1,-3)], [26,22,()=>seesaw(c,26,22)]];objects.sort((a,b)=>(a[0]+a[1])-(b[0]+b[1]));for(const o of objects)o[2]();
// Tiny deterministic field marks and leaf texture, no random simulation inputs.
for(let i=0;i<200;i++){const x=-4+rnd(i)*32,y=-3+rnd(i+900)*26;if(x>-.6&&x<24.6&&y>-.6&&y<20.6)continue;local(c,x,y,()=>line(c,[[0,0],[2,-2],[4,0]],'#84906644',.8))}
local(c,23,24.5,()=>{c.fillStyle='#84906d';c.font='9px monospace';c.textAlign='center';c.fillText('PLAY, TOGETHER.',0,0)});return out}
const SKIN=['#e9bc91','#b9805c','#f0cba8','#976340'];const TOP=['#cf7d61','#7098a3','#d6b25b','#87976f','#ece5d0','#a58a9e'];
export function drawChild(c,p,now,scale=1,alpha=1,sprite=null){const phase=p.seed*.91,move=p.seed%4;const bounce=move===1?Math.max(0,Math.sin(now*.003+phase))*3:Math.sin(now*.002+phase)*.6;c.save();c.translate(p.wx,p.wy);c.globalAlpha=alpha;shadow(c,2,1,7,2.4);c.translate(0,-bounce);c.scale(scale,scale);
if(sprite?.complete&&sprite.naturalWidth){const sw=sprite.naturalWidth/4,sh=sprite.naturalHeight/2,k=p.seed%8;c.drawImage(sprite,k%4*sw,Math.floor(k/4)*sh,sw,sh,-20,-52,40,58);c.restore();return}
// Independent vector fallback, also used while illustrated atlas loads.
const skin=SKIN[p.seed%4],shirt=TOP[p.seed%6],hair=['#4d4134','#69513a','#3d3932'][p.seed%3];
line(c,[[-3,-13],[-3,-3]],'#7a8270',4);line(c,[[3,-13],[3,-3]],'#7a8270',4);line(c,[[-3,-2],[-5,-2]],'#424b41',3);line(c,[[3,-2],[5,-2]],'#424b41',3);
poly(c,[[-6,-27],[5,-27],[6,-13],[-6,-13]],shirt,INK,.7);line(c,[[-5,-24],[-9,-18],[-10,-15]],skin,3);const wave=Math.sin(now*.004+phase)*2;line(c,[[5,-24],[9,-28],[11+wave,-34]],skin,3);
ellipse(c,0,-34,7,8,skin,INK);c.beginPath();c.arc(0,-36,7,Math.PI,Math.PI*2);c.fillStyle=hair;c.fill();poly(c,[[-7,-37],[-3,-41],[6,-38],[3,-35],[0,-37],[-5,-34]],hair);
if(p.seed%3===1)ellipse(c,-7,-37,3,3,hair);ellipse(c,-2,-34,.6,.7,'#413e32');ellipse(c,3,-34,.6,.7,'#413e32');line(c,[[-1,-30],[1,-29],[3,-30]],'#8d5b48',.65);line(c,[[-2,-25],[1,-22],[3,-25]],'#f6efdd',1);c.restore()}
export function highlight(c,x,y,color){plane(c,x,y,1,1,color,'#77846090')}
